CREATE OR REPLACE FUNCTION public.app_td_admin_import_questions_json(p_questions jsonb, p_subject text DEFAULT NULL::text, p_bank_id uuid DEFAULT NULL::uuid, p_source text DEFAULT 'admin_import'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_uid uuid;
    v_count integer := 0;
    v_q jsonb;
    i integer;
BEGIN
    v_uid := auth.uid();
    IF v_uid IS NULL THEN
        RAISE EXCEPTION 'Non authentifié';
    END IF;

    FOR i IN 0..jsonb_array_length(p_questions) - 1 LOOP
        v_q := p_questions->i;

        INSERT INTO app.td_questions (
            bank_id, question_type, content, options, correct_index,
            explanation, difficulty, subject, created_by, is_active
        ) VALUES (
            p_bank_id,
            COALESCE(v_q->>'question_type', 'mcq'),
            COALESCE(v_q->>'question', v_q->>'content', ''),
            v_q->'options',
            COALESCE((v_q->>'correct_index')::integer, 0),
            v_q->>'explanation',
            COALESCE((v_q->>'difficulty')::integer, 2),
            COALESCE(p_subject, v_q->>'subject', 'Général'),
            v_uid,
            true
        );
        v_count := v_count + 1;
    END LOOP;

    RETURN jsonb_build_object(
        'success', true,
        'imported_count', v_count,
        'source', p_source
    );
END;
$function$

